"""Drug-specific plain-language text for the medications that appear in the class materials (so a drug's page never describes OTHER drugs).
Same rules as extras.py: my own wording from standard references (FDA labeling, nursing pharmacology texts), no doses.
Lab targets that appear in the class materials (aPTT, INR, digoxin and lithium levels...) are kept because they are monitoring targets, not doses.
Fields: cl (what it is), moa, admin, se, labs, nsg; items separated by '|'."""
CORE={}
def E(names,cl,moa,adm,se,labs,nsg):
    for n in ([names] if isinstance(names,str) else names):
        CORE[n]=dict(cl=cl,moa=moa,admin=adm,se=se,labs=labs,nsg=nsg)
def X(name,**kw):                                   # add one drug's own extra lines after the shared text
    for k,v in kw.items():CORE[name][k]=CORE[name][k]+'|'+v
